/* ═══════════════════════════════════════════════════════════════
   A방식: Supabase Auth + RLS + aba_data 어댑터
   ───────────────────────────────────────────────────────────────
   - 로그인: Supabase Auth (이메일+비번). 세션은 localStorage에 저장.
   - 데이터: 모든 데이터는 "관리자 소유(aba_data)" 한 곳에 저장 → 모두 공유.
     선생님별 "자기 아동만" 격리는 앱 화면 filter가 담당 (기존 로직 유지).
   - window.storage.get/set/delete/list 인터페이스는 기존과 동일하게 유지.
     (shared 파라미터는 무시 — 전부 공용 데이터)
   ═══════════════════════════════════════════════════════════════ */

// 공용 데이터 소유자 = 관리자(민다혜) user_id
const ABA_OWNER_ID = "aecb8a9c-000e-4ad5-9805-83450e9bc585";

// ── Auth 세션 관리 ──────────────────────────────────────────────
const AUTH_SESSION_KEY = "sb-aba-auth-session";

function _getStoredSession() {
  try {
    const raw = sessionStorage.getItem(AUTH_SESSION_KEY);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch (e) { return null; }
}
function _saveSession(session) {
  try {
    if (session) sessionStorage.setItem(AUTH_SESSION_KEY, JSON.stringify(session));
    else sessionStorage.removeItem(AUTH_SESSION_KEY);
  } catch (e) {}
}
async function _refreshSession(refreshToken) {
  try {
    const r = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "apikey": SUPABASE_ANON_KEY },
      body: JSON.stringify({ refresh_token: refreshToken }),
    });
    if (!r.ok) return null;
    const data = await r.json();
    if (data.access_token) { _saveSession(data); return data; }
    return null;
  } catch (e) { return null; }
}
async function _getValidAccessToken() {
  const session = _getStoredSession();
  if (!session) return null;
  // 만료 5분 전이면 refresh
  const nowSec = Math.floor(Date.now() / 1000);
  if (session.expires_at && session.expires_at > nowSec + 300 && session.access_token) {
    return session.access_token;
  }
  if (session.refresh_token) {
    const refreshed = await _refreshSession(session.refresh_token);
    if (refreshed?.access_token) return refreshed.access_token;
  }
  return session.access_token || null;
}
async function _authHeaders() {
  const token = await _getValidAccessToken();
  return {
    "apikey": SUPABASE_ANON_KEY,
    "Authorization": token ? `Bearer ${token}` : `Bearer ${SUPABASE_ANON_KEY}`,
    "Content-Type": "application/json",
  };
}

// ── Auth API ────────────────────────────────────────────────────
async function abaSignIn(email, password) {
  try {
    const r = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "apikey": SUPABASE_ANON_KEY },
      body: JSON.stringify({ email, password }),
    });
    const data = await r.json();
    if (!r.ok) return { error: data.error_description || data.msg || data.error || "로그인 실패" };
    _saveSession(data);
    return { session: data, user: data.user };
  } catch (e) { return { error: "네트워크 오류: " + e.message }; }
}
async function abaSignOut() {
  try {
    const token = await _getValidAccessToken();
    if (token) {
      await fetch(`${SUPABASE_URL}/auth/v1/logout`, {
        method: "POST",
        headers: { "apikey": SUPABASE_ANON_KEY, "Authorization": `Bearer ${token}` },
      });
    }
  } catch (e) {}
  _saveSession(null);
}
async function abaGetCurrentUser() {
  try {
    const token = await _getValidAccessToken();
    if (!token) return null;
    const r = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
      headers: { "apikey": SUPABASE_ANON_KEY, "Authorization": `Bearer ${token}` },
    });
    if (!r.ok) return null;
    return await r.json();
  } catch (e) { return null; }
}

// ── 관리자용 계정 관리 (Edge Function admin-users) ───────────────
async function abaAdminCreateUser(email, password, displayName) {
  try {
    const headers = await _authHeaders();
    const r = await fetch(`${SUPABASE_URL}/functions/v1/admin-users`, {
      method: "POST", headers,
      body: JSON.stringify({ action: "create", email, password, display_name: displayName || email.split("@")[0] }),
    });
    const data = await r.json();
    if (!r.ok) return { error: data.error || "계정 생성 실패" };
    return { user: data.user };
  } catch (e) { return { error: "네트워크 오류: " + e.message }; }
}
async function abaAdminDeleteUser(userId) {
  try {
    const headers = await _authHeaders();
    const r = await fetch(`${SUPABASE_URL}/functions/v1/admin-users`, {
      method: "POST", headers,
      body: JSON.stringify({ action: "delete", user_id: userId }),
    });
    if (!r.ok) { const d = await r.json().catch(() => ({})); return { error: d.error || "삭제 실패" }; }
    return { ok: true };
  } catch (e) { return { error: "네트워크 오류: " + e.message }; }
}
async function abaAdminUpdatePassword(userId, newPassword) {
  try {
    const headers = await _authHeaders();
    const r = await fetch(`${SUPABASE_URL}/functions/v1/admin-users`, {
      method: "POST", headers,
      body: JSON.stringify({ action: "update_password", user_id: userId, password: newPassword }),
    });
    const data = await r.json();
    if (!r.ok) return { error: data.error || "비번 변경 실패" };
    return { ok: true };
  } catch (e) { return { error: "네트워크 오류: " + e.message }; }
}
async function abaAdminListUsers() {
  try {
    const headers = await _authHeaders();
    const r = await fetch(`${SUPABASE_URL}/rest/v1/rpc/admin_list_users`, {
      method: "POST", headers, body: "{}",
    });
    if (!r.ok) return [];
    return await r.json();
  } catch (e) { return []; }
}

// ── 데이터 저장/조회 (aba_data — 관리자 소유 고정, 모두 공유) ─────
window.storage = {
  // ★ [95-1] 읽기 실패는 반드시 예외로 알린다 — "키 없음"과 구분해야 한다.
  //    저장 경로의 [60-15] 가드(cloudReadOk)는 get()이 실패에 예외를 던지던
  //    옛 어댑터를 전제로 짜여 있다. 이 Supabase 어댑터가 실패에도 null을
  //    돌려주면서 그 가드가 죽어 있었다 — 읽기가 실패해도 cloudReadOk=true가 되어
  //    cloudChildren이 null인 채 병합을 건너뛰고, 이 기기 사본만 클라우드로
  //    통째 올라갔다(storage.set은 키 전체를 갈아치운다).
  //    83-1·89-1의 병합 보호는 멀쩡한데 mergeChildren을 아예 안 타므로
  //    호출조차 되지 않는 자리였다.
  //      (배유민 — 목표 13개는 그대로인데 daily만 0.
  //       코드에 daily를 비우는 경로가 없는 게 맞다. 지워진 게 아니라,
  //       daily가 없던 낡은 로컬 사본이 멀쩡한 클라우드를 덮은 것이다.)
  //    행이 0건인 것(= 아직 저장된 적 없는 키)만 null로 두고, 장애는 던진다.
  //    호출부 18곳은 모두 try/catch 안에 있어 예외가 새어 나가지 않는다.
  async get(key /*, shared */) {
    const headers = await _authHeaders();
    const url = `${SUPABASE_URL}/rest/v1/aba_data?user_id=eq.${ABA_OWNER_ID}&key=eq.${encodeURIComponent(key)}&select=value`;
    let r;
    try {
      r = await fetch(url, { headers });
    } catch (e) {
      console.warn("[aba get 예외]", key, e);
      throw new Error("cloud read failed (network): " + (e && e.message ? e.message : "unknown"));
    }
    if (!r.ok) {
      console.warn("[aba get]", key, r.status);
      throw new Error("cloud read failed (HTTP " + r.status + ")");
    }
    let rows;
    try {
      rows = await r.json();
    } catch (e) {
      console.warn("[aba get 본문 파싱 실패]", key, e);
      throw new Error("cloud read failed (bad body)");
    }
    return (rows && rows.length > 0) ? { value: rows[0].value } : null;
  },

  // ★ [97-1] 값(value)은 빼고 updated_at 컬럼 하나만 읽는다.
  //    5초 폴링이 하던 일은 "누가 나보다 나중에 고쳤나" 시각 비교뿐인데,
  //    그걸 위해 get()으로 아동 전체·목표 전체·회기 기록 전체를 통째로 내려받고 있었다.
  //    한 번에 약 380KB × 5초마다 × 선생님 수 × 하루 8시간 = 하루 6.5GB.
  //    무료 한도가 월 5GB인데 8월 한 달에 37.4GB(748%)를 써서 프로젝트 전체가 정지됐다.
  //    (2026-09-03. 아무도 로그인할 수 없었다.)
  //    이 함수는 한 번에 약 30바이트다 — 같은 일을 1만분의 3의 전송량으로 한다.
  //    실제로 바뀌었을 때만 아래에서 get()으로 본문을 받는다.
  //    실패 처리는 get과 동일: 장애는 던지고, 행이 없을 때만 null.
  async getStamp(key /*, shared */) {
    const headers = await _authHeaders();
    const url = `${SUPABASE_URL}/rest/v1/aba_data?user_id=eq.${ABA_OWNER_ID}&key=eq.${encodeURIComponent(key)}&select=updated_at`;
    let r;
    try {
      r = await fetch(url, { headers });
    } catch (e) {
      console.warn("[aba getStamp 예외]", key, e);
      throw new Error("cloud read failed (network): " + (e && e.message ? e.message : "unknown"));
    }
    if (!r.ok) {
      console.warn("[aba getStamp]", key, r.status);
      throw new Error("cloud read failed (HTTP " + r.status + ")");
    }
    let rows;
    try {
      rows = await r.json();
    } catch (e) {
      console.warn("[aba getStamp 본문 파싱 실패]", key, e);
      throw new Error("cloud read failed (bad body)");
    }
    return (rows && rows.length > 0) ? { updatedAt: rows[0].updated_at } : null;
  },

  // ★ [96-1] 저장 실패도 예외로 알린다 — get과 같은 이유.
  //    실패에 null을 돌려주면 호출부는 저장된 줄 알고 다음 단계로 넘어간다.
  //    가장 위험한 자리는 스냅샷 되돌리기다: 되돌리기 전에 '지금 상태'를 안전 스냅샷으로
  //    남기고 나서 children을 덮어쓰는데, 그 안전 스냅샷 저장이 조용히 실패해도
  //    덮어쓰기는 그대로 진행됐다 — 되돌린 뒤 그날 이후 기록을 복구할 방법이 사라진다.
  //    예외를 던지면 덮어쓰기 전에 catch로 빠져 되돌리기 자체가 중단된다.
  //    스냅샷 저장도 본체와 목록이 함께 실패하게 되어, 없는 스냅샷이 목록에 남지 않는다.
  //    호출부 18곳은 모두 try/catch 또는 .catch() 안에 있어 예외가 새어 나가지 않는다.
  async set(key, value /*, shared */) {
    const headers = await _authHeaders();
    let r;
    try {
      r = await fetch(`${SUPABASE_URL}/rest/v1/aba_data`, {
        method: "POST",
        headers: { ...headers, "Prefer": "resolution=merge-duplicates,return=minimal" },
        body: JSON.stringify({ user_id: ABA_OWNER_ID, key, value, updated_at: new Date().toISOString() }),
      });
    } catch (e) {
      console.warn("[aba set 예외]", key, e);
      throw new Error("cloud write failed (network): " + (e && e.message ? e.message : "unknown"));
    }
    if (!r.ok) {
      console.warn("[aba set]", key, r.status);
      throw new Error("cloud write failed (HTTP " + r.status + ")");
    }
    return { value };
  },

  async delete(key /*, shared */) {
    try {
      const headers = await _authHeaders();
      const url = `${SUPABASE_URL}/rest/v1/aba_data?user_id=eq.${ABA_OWNER_ID}&key=eq.${encodeURIComponent(key)}`;
      await fetch(url, { method: "DELETE", headers });
      return { deleted: true };
    } catch (e) { console.warn("[aba delete 예외]", e); return null; }
  },

  async list(prefix /*, shared */) {
    try {
      const headers = await _authHeaders();
      const filter = prefix ? `&key=like.${encodeURIComponent(prefix)}*` : "";
      const url = `${SUPABASE_URL}/rest/v1/aba_data?user_id=eq.${ABA_OWNER_ID}&select=key${filter}`;
      const r = await fetch(url, { headers });
      if (!r.ok) { console.warn("[aba list]", r.status); return { keys: [] }; }
      const rows = await r.json();
      return { keys: (rows || []).map(row => row.key) };
    } catch (e) { console.warn("[aba list 예외]", e); return { keys: [] }; }
  },
};


