function classifyCurriculum(domain) {
  if (!domain) return "other";
  const cleanDom = domain.replace(/^[Ⅰ-Ⅺ]\s*/, "").trim();
  if (typeof VBMAPP_DOMAINS !== "undefined" && Array.isArray(VBMAPP_DOMAINS)) {
    for (const v of VBMAPP_DOMAINS) {
      const vName = (v.d || "").replace(/\s*\(.+?\)\s*/, "").trim(); // "Mand (요구)" → "Mand"
      if (vName && cleanDom.includes(vName)) return "vbmapp";
    }
  }
  if (typeof ELCAR !== "undefined" && Array.isArray(ELCAR)) {
    for (const e of ELCAR) {
      const elcClean = (e.d || "").replace(/^[Ⅰ-Ⅺ]\s*/, "").trim();
      if (elcClean && (cleanDom === elcClean || (e.d || "").trim() === domain.trim())) return "elcar";
    }
  }
  // ★ [59-2] ESDM_DOMAINS는 배열인데 레벨→영역 객체처럼 훑고 있었다.
  //    Object.keys(배열)은 "0","1"… 이고 그 원소의 키는 d·s라, 이 분기는 한 번도 걸리지 않았다.
  //    (실제 분류는 아래 문자열 포함 검사가 대신 하고 있었다 — 영역명이 늘면 놓친다)
  if (typeof ESDM_DOMAINS !== "undefined" && Array.isArray(ESDM_DOMAINS)) {
    for (const e of ESDM_DOMAINS) {
      if ((e.d || "").trim() === cleanDom || (e.d || "").trim() === (domain || "").trim()) return "esdm";
    }
  }
  const d = (domain || "").toLowerCase();
  if (d.includes("vb-mapp") || d.includes("vbmapp") || d.includes("mand") || d.includes("tact") || d.includes("listener") || d.includes("echoic") || d.includes("intraverbal") || d.includes("vp/mts") || d.includes("lrffc")) return "vbmapp";
  if (d.includes("esdm") || d.includes("수용 언어") || d.includes("표현 언어") || d.includes("자조") || d.includes("개인적 독립") || d.includes("합동 주시")) return "esdm";
  if (d.includes("선호물") || d.includes("강화제") || d.includes("조건화") || d.includes("화자") || d.includes("청자") || d.includes("교수") || d.includes("자기관리") || d.includes("언어행동") || d.includes("학습능력") || d.includes("신체발달") || d.includes("elcar")) return "elcar";
  return "other";
}

const PAUSE_REASON_MAP = {
  "일반화 어려움": "치료실 외 환경(가정 등)에서의 안정적 수행을 확인한 후, 점진적인 환경 확장을 통해 재개할 예정입니다.",
  "선행 기술 부족": "필요한 선행 기술의 기초를 충분히 다져 성공 경험을 높인 후, 더 안정적으로 재시작할 예정입니다.",
  "아동 컨디션 변화": "아동의 정서와 학습 효율을 최우선으로 고려하여 잠시 보류하였으며, 컨디션이 회복되는 시점에 부드럽게 재개하겠습니다.",
  "가정 환경 변화": "가정 내 변화에 따른 새로운 루틴에 맞추어 중재 방향을 최적화한 후 재개할 예정입니다.",
  "우선순위 조정": "현재 시기에 더 시급한 핵심 기술 습득을 위해 전략적으로 순서를 조정하였으며, 적절한 시점에 다시 진행하겠습니다.",
  "도구·자료 부족": "더 효과적인 교구와 시각 자료를 보완한 후, 한층 풍부한 학습 환경에서 재개할 예정입니다."
};

function softenPauseReason(raw) {
  if (!raw || typeof raw !== "string") return "";
  const text = raw.trim();
  if (!text) return "";
  if (PAUSE_REASON_MAP[text]) return PAUSE_REASON_MAP[text];
  const NEG_PATTERNS = [
    { re: /너무\s*어렵|너무\s*힘들|어려워|어려움|난이도\s*높/, soft: "난이도 재조정 및 세부 단계 분석(Task Analysis) 후 재개 예정" },
    { re: /못\s*함|못함|못해|불가능|안\s*됨|안됨|실패/, soft: "충분한 선행 기술을 다진 후 단계적으로 재개 예정" },
    { re: /거부|싫어함|싫어|짜증|울음|문제행동/, soft: "아동의 정서적 안정과 학습 동기를 우선 고려하여 적절한 시점에 재개 예정" },
    { re: /지루|흥미\s*없|관심\s*없|동기\s*없|재미\s*없/, soft: "강화제 재평가 및 흥미 유발 요소 보완 후 재개 예정" },
    { re: /시간\s*부족|시간\s*없|일정/, soft: "회기 일정 조정을 통해 충분한 연습 시간 확보 후 재개 예정" },
    { re: /부모\s*거부|보호자\s*반대|가정\s*반대/, soft: "가정과의 충분한 소통을 거쳐 협의된 방향으로 재개 예정" }
  ];
  for (const p of NEG_PATTERNS) {
    if (p.re.test(text)) return p.soft;
  }
  return text;
}

const CUR_FIELDS = ["언어","사회성","문제행동 / 주의 집중","교수 참여도 및 반응성","최근 변화"];

const IS = { width: "100%", border: "1px solid #e8d0d6", borderRadius: 8, padding: "7px 10px", fontSize: 13, fontFamily: "inherit", outline: "none", boxSizing: "border-box" };
const LS = { display: "block", fontSize: 12, color: "#767676", marginBottom: 4 };

// ★ [56-1] 회당 N분 선택 상자.
//    기존엔 이 컴포넌트를 '회당 N분' 칸을 그리는 즉시실행함수 안에서 정의했다.
//    그러면 부모가 다시 그려질 때마다 컴포넌트 '종류'가 매번 새로 만들어져,
//    React가 같은 자리를 갱신하지 않고 통째로 떼었다 다시 붙인다.
//    → 값을 고르는 순간 select가 새로 마운트되면서 선택이 반영되지 않았다.
//    모듈 최상위로 올려 한 번만 정의한다.
//    ★ 값 비교도 문자열로 통일 — 저장된 값이 숫자 50이면 value === "50"이 거짓이 돼
//      '직접입력' 상태로 잘못 잡히고, 상자가 64px로 좁아진 채 빈칸처럼 보였다.
function SessionMinSelect({ value, onChange, label }) {
  const v = (value == null) ? "" : String(value);
  const isPreset = v === "50" || v === "100";
  const isCustom = v !== "" && !isPreset;
  const selectValue = isPreset ? v : (isCustom ? "custom" : "");
  return (
    <div style={{ display: "flex", gap: 4, alignItems: "center" }}>
      {label && <span style={{ fontSize: 10, color: "#888", whiteSpace: "nowrap", minWidth: 34 }}>{label}</span>}
      <select
        style={{ ...IS, padding: "5px 6px", fontSize: 11.5, flex: isCustom ? "0 0 74px" : 1, minWidth: 68 }}
        value={selectValue}
        onChange={e => onChange(e.target.value === "custom" ? "" : e.target.value)}>
        <option value="">선택</option>
        <option value="50">50분</option>
        <option value="100">100분</option>
        <option value="custom">직접입력</option>
      </select>
      {isCustom && (
        <input type="text" inputMode="numeric" placeholder="예: 40"
          style={{ ...IS, padding: "5px 8px", fontSize: 11.5, flex: 1 }}
          value={v}
          onChange={e => onChange(e.target.value)} />
      )}
    </div>
  );
}
const CS = { background: "#fff", border: "1px solid #f0e0e5", borderRadius: 14, padding: "1.25rem", marginBottom: "1rem" };
const BS = { border: `1px solid ${PK}`, borderRadius: 8, padding: "8px 18px", fontSize: 13, background: "transparent", color: PKD, cursor: "pointer", fontFamily: "inherit" };
const BP = { ...BS, background: PK, color: "#fff" };

/* ═══════════════════════════════════════════════════════════════
   ★ [시간표 연결] 선생님 화면 '내 일정' 칸 — 시간표 앱(geomdan-schedule) 데이터를 읽기만 함
   - 같은 Supabase · 같은 로그인이라, 서버 권한(RLS)이 이 선생님 수업 · 문구만 내려줍니다.
   - 시간표 앱 데이터에 쓰지 않습니다. 통합본 아동 데이터와도 무관합니다.
   - 읽기가 실패하면 칸을 그리지 않고 조용히 넘어갑니다(통합본 다른 기능에 영향 없음).
   ═══════════════════════════════════════════════════════════════ */
const SCHED_APP_URL = "https://aba-geomdan.github.io/geomdan-schedule/";
async function schedRead(path, headers) {
  const r = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, { headers });
  if (!r.ok) throw new Error("schedule read " + r.status);
  const j = await r.json();
  return Array.isArray(j) ? j : [];
}
const _sIso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
const _sClock = (t) => {
  if (!t) return "";
  const [H, M] = String(t).slice(0, 5).split(":");
  return `${((Number(H) + 11) % 12) + 1}:${M}`;
};
const _sMd = (d) => `${Number(String(d).slice(5, 7))}/${Number(String(d).slice(8, 10))}(${"일월화수목금토"[new Date(String(d).slice(0, 10) + "T00:00:00").getDay()]})`;

// 로그인한 사람의 시간표 앱 선생님 id (원장님도 본인 수업만 보이게 하려고) — 못 찾으면 null
async function schedMyStaffId(headers) {
  const r = await fetch(`${SUPABASE_URL}/auth/v1/user`, { headers });
  if (!r.ok) return null;
  const u = await r.json();
  if (!u?.id) return null;
  const rows = await schedRead(`staff?select=id&auth_user_id=eq.${u.id}&limit=1`, headers);
  return rows[0]?.id || null;
}

function TeacherScheduleStrip({ isAdmin = false }) {
  const [data, setData] = useState(null); // null = 아직 / 실패 → 칸 안 그림
  const [open, setOpen] = useState(() => {
    try { return localStorage.getItem("aba-sched-strip-open") !== "0"; } catch (e) { return true; }
  });
  useEffect(() => {
    let on = true;
    let seq = 0;        // 늦게 끝난 예전 요청이 최신 값을 덮지 않게
    let lastAt = 0;     // 마지막으로 읽은 시각 (창을 자주 오가도 1분 안에는 다시 읽지 않음)
    let staffId;        // 시간표 앱의 내 선생님 id (처음 한 번만 찾음)
    const pull = async () => {
      const my = ++seq;
      lastAt = Date.now();
      try {
        const headers = await _authHeaders(); // 로그인 토큰은 한 번만 받아 여러 요청에 같이 씀
        if (!staffId) staffId = await schedMyStaffId(headers).catch(() => null); // 못 찾았으면 다음에 다시 시도
        // 원장님 계정은 서버가 모든 선생님 수업을 내려주므로, 본인 id를 못 찾으면 칸을 그리지 않음
        if (isAdmin && !staffId) return;
        const mine = staffId ? `&staff_id=eq.${staffId}` : "";
        const now = new Date();
        const mon = new Date(now); mon.setDate(now.getDate() - ((now.getDay() + 6) % 7));
        const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
        // 셋 중 하나가 실패해도 나머지는 보여 줌
        const [ss, um, nt] = await Promise.allSettled([
          schedRead(`v_sessions?select=id,d,start_time,end_time,status,student_name,makeup_for&d=gte.${_sIso(mon)}&d=lte.${_sIso(sun)}&status=neq.${encodeURIComponent("취소")}${mine}&order=d.asc,start_time.asc`, headers),
          schedRead(`v_unmade_up?select=id${mine}`, headers),
          // 선생님: 원장님이 보낸 문구 / 원장님: 선생님이 보낸 보강 체크 · 마감 답 (확인 안 한 것)
          isAdmin
            ? schedRead(`notices?select=id,kind,message,created_at,from_staff,payload&confirmed_at=is.null&to_staff=is.null&kind=in.(report,close_ans)&order=created_at.desc&limit=30`, headers)
            : schedRead(`notices?select=id,kind,message,created_at,to_staff,payload&confirmed_at=is.null&to_staff=not.is.null&order=created_at.desc&limit=30`, headers),
        ]);
        if (!on || my !== seq) return;
        // 처음부터 수업 목록을 못 읽으면 칸을 그리지 않음 (시간표 앱과 연결 안 된 상태)
        if (ss.status !== "fulfilled") return;
        setData({
          ss: ss.value,
          unmade: um.status === "fulfilled" ? um.value.length : 0,
          nt: nt.status === "fulfilled" ? nt.value : [],
          today: _sIso(now),
        });
      } catch (e) {
        // 잠깐 네트워크가 끊겨도 마지막으로 읽은 내용은 그대로 둡니다
      }
    };
    pull();
    const iv = setInterval(() => { if (document.visibilityState === "visible") pull(); }, 5 * 60 * 1000); // 5분마다, 창을 보고 있을 때만
    const vis = () => { if (document.visibilityState === "visible" && Date.now() - lastAt > 60 * 1000) pull(); };
    document.addEventListener("visibilitychange", vis);
    return () => { on = false; clearInterval(iv); document.removeEventListener("visibilitychange", vis); };
  }, [isAdmin]);
  if (!data) return null;
  const toggle = () => {
    const v = !open; setOpen(v);
    try { localStorage.setItem("aba-sched-strip-open", v ? "1" : "0"); } catch (e) {}
  };
  const closeReq = isAdmin ? [] : data.nt.filter((n) => n.kind === "close_req");
  const changes = isAdmin ? [] : data.nt.filter((n) => n.kind !== "close_req");
  const fromTeachers = isAdmin ? data.nt : []; // 원장님: 선생님이 보낸 보강 체크 · 마감 답
  const todays = data.ss.filter((s) => String(s.d).slice(0, 10) === data.today);
  const weekMakeups = data.ss.filter((s) => s.status === "보강" && String(s.d).slice(0, 10) >= data.today);
  const chip = (bg, fg, text) => (
    <span style={{ fontSize: 10.5, fontWeight: 700, color: fg, background: bg, borderRadius: 99, padding: "1px 8px", whiteSpace: "nowrap", flexShrink: 0 }}>{text}</span>
  );
  const goBtn = (label) => (
    <a href={SCHED_APP_URL} target="_blank" rel="noopener noreferrer"
      style={{ ...BS, padding: "3px 10px", fontSize: 11, textDecoration: "none", whiteSpace: "nowrap", display: "inline-block" }}>
      {label}
    </a>
  );
  return (
    <div style={{ marginBottom: 10, border: `1.5px solid ${PK}`, borderRadius: 10, background: "#fff", overflow: "hidden" }}>
      <div onClick={toggle} role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggle(); } }}
        style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 13px", background: PKL, cursor: "pointer", flexWrap: "wrap" }}>
        <span style={{ fontSize: 12.5, fontWeight: 800, color: PKD }}>📅 내 일정</span>
        {closeReq.length > 0 && chip("#1d4d80", "#fff", "마감 확인 요청")}
        {changes.length > 0 && chip("#E07B00", "#fff", `일정 변경 ${changes.length}`)}
        {fromTeachers.length > 0 && chip("#1d4d80", "#fff", `선생님 확인 ${fromTeachers.length}`)}
        {data.unmade > 0 && chip("#FDECEF", "#AE2340", `보강 안 된 결강 ${data.unmade}`)}
        <span style={{ flex: 1 }} />
        <span onClick={(e) => e.stopPropagation()}>{goBtn("시간표 앱 열기 ↗")}</span>
        <span style={{ fontSize: 11, color: "#b98a96" }}>{open ? "▾ 접기" : "▸ 펼치기"}</span>
      </div>
      {open && (
        <div style={{ padding: "9px 13px", display: "flex", flexDirection: "column", gap: 8 }}>
          {closeReq.length > 0 && (
            <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", padding: "7px 10px", borderRadius: 8, background: "#f0f6fb", border: "1px solid #b9d4ee", fontSize: 12, color: "#1d4d80" }}>
              <span style={{ flex: 1, minWidth: 200 }}>
                🧾 <b>원장님이 {closeReq[0].payload?.ym ? `${Number(String(closeReq[0].payload.ym).slice(5))}월 ` : ""}마감 확인을 요청했습니다.</b> 시간표 앱 '마감'에서 맞는지 확인해 주세요.
              </span>
              {goBtn("확인하러 가기 ↗")}
            </div>
          )}
          {fromTeachers.length > 0 && (
            <div style={{ padding: "7px 10px", borderRadius: 8, background: "#f0f6fb", border: "1px solid #b9d4ee", fontSize: 12, color: "#1d4d80" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4, flexWrap: "wrap" }}>
                <b style={{ flex: 1 }}>선생님이 보낸 확인할 것 ({fromTeachers.length}건)</b>
                {goBtn("시간표 앱에서 처리 ↗")}
              </div>
              {fromTeachers.slice(0, 3).map((n) => (
                <div key={n.id} style={{ lineHeight: 1.6 }}>· {n.kind === "report" ? "[보강 체크] " : n.payload?.agree ? "[마감 같음] " : "[마감 다름] "}{n.message}</div>
              ))}
              {fromTeachers.length > 3 && <div style={{ color: "#6a8cb0" }}>외 {fromTeachers.length - 3}건</div>}
            </div>
          )}
          {changes.length > 0 && (
            <div style={{ padding: "7px 10px", borderRadius: 8, background: "#fffaf0", border: "1px solid #e8d5a8", fontSize: 12, color: "#7a5a10" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4, flexWrap: "wrap" }}>
                <b style={{ flex: 1 }}>원장님이 일정을 바꿨습니다 ({changes.length}건)</b>
                {goBtn("시간표 앱에서 확인 ↗")}
              </div>
              {changes.slice(0, 3).map((n) => (
                <div key={n.id} style={{ lineHeight: 1.6 }}>· {n.message}</div>
              ))}
              {changes.length > 3 && <div style={{ color: "#a8946a" }}>외 {changes.length - 3}건</div>}
            </div>
          )}
          <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
            <div style={{ flex: "1 1 220px", minWidth: 0 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#999", marginBottom: 4 }}>오늘 수업</div>
              {todays.length === 0 && <div style={{ fontSize: 12, color: "#aaa" }}>오늘은 수업이 없습니다</div>}
              {todays.map((s) => (
                <div key={s.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12.5, padding: "3px 0" }}>
                  <span style={{ width: 82, color: "#888", flexShrink: 0 }}>{_sClock(s.start_time)}~{_sClock(s.end_time)}</span>
                  <span style={{ fontWeight: 700, color: s.status === "결강" ? "#aaa" : "#333", textDecoration: s.status === "결강" ? "line-through" : "none" }}>{s.student_name}</span>
                  {s.status === "보강" && chip("#E07B00", "#fff", "보강")}
                  {s.status === "결강" && chip("#FDECEF", "#AE2340", "결강")}
                </div>
              ))}
            </div>
            <div style={{ flex: "1 1 220px", minWidth: 0 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#999", marginBottom: 4 }}>이번 주 보강</div>
              {weekMakeups.length === 0 && <div style={{ fontSize: 12, color: "#aaa" }}>남은 보강이 없습니다</div>}
              {weekMakeups.map((s) => (
                <div key={s.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12.5, padding: "3px 0" }}>
                  <span style={{ width: 54, color: "#888", flexShrink: 0 }}>{_sMd(s.d)}</span>
                  <span style={{ width: 82, color: "#888", flexShrink: 0 }}>{_sClock(s.start_time)}~{_sClock(s.end_time)}</span>
                  <span style={{ fontWeight: 700, color: "#333" }}>{s.student_name}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}


// ★ [63-1] ELCAR 커리큘럼 항목 교체 — 옛 328항목 → 새 722라벨.
//    옛 목록은 영역/세부영역 분류가 실제 ELCAR과 어긋나 있었다(예: 준거기준이
//    항목처럼 섞임, 소영역 코드가 책과 불일치). 원장님이 책 기준으로 다시 정리한
//    JSON으로 통째 교체한다. 항목 문구는 "번호. 내용" 형태로 통일했고,
//    하위 항목이 있는 문항은 "39-a. 상위문항 — 하위문항"으로 편다.
//    ★ 상위 문항 본문을 반드시 같이 넣는다. 안 넣으면 하위만 남아
//      "1-a. 응시 이동"과 "2-a. 응시 이동"이 화면에서 구분되지 않는다
//      (1=어른이 시도한 공유 관심, 2=또래가 시도한 공유 관심).
//      "3-a. 어른과"처럼 하위만으로는 뜻이 성립하지 않는 문항도 많다.
//      소영역 안에서 라벨 유일함을 확인했다(중복 0건).
//
//    기존 아동 목표는 건드리지 않는다.
//    goals는 자기 domain/subDomain/item 문자열을 들고 있고, 목표 목록·데일리·
//    보고서는 카탈로그를 거치지 않고 goals를 직접 읽는다(includedGoals).
//    카탈로그와 대조하는 곳은 커리큘럼 화면의 체크 표시 한 군데뿐이라,
//    옛 항목으로 담아둔 목표는 그대로 살아 있고 화면에서 체크만 안 보인다.
//    옛→새 자동 대응은 하지 않는다 — 이름이 비슷하다는 이유로 짝지으면
//    (328개 중 190개가 부분일치 수준) 멀쩡한 아동 목표가 조용히 다른 항목으로
//    바뀔 수 있다. 데이터를 건드리는 쪽이 더 위험하다.
