//    클라우드 스냅샷(85-2)은 클라우드가 통째로 잘못되면 같이 사라진다.
//    그 경우까지 대비해 손에 남는 파일을 한 달에 하나는 갖게 한다.
//    자동 다운로드는 브라우저가 막을 수 있어, 알려주고 한 번 누르게 한다.
const MONTHLY_BACKUP_KEY = "gd-aba-monthly-backup";
// ★ [59-4] ESDM 항목 저장 키 — 문항은 코드가 아니라 데이터로 산다.
//    관리자가 항목 편집 화면에서 직접 입력하면 Supabase(aba_data)에 저장되고,
//    모든 선생님의 커리큘럼 화면에 ELCAR와 같은 방식으로 나타난다.
//    형식: { "영역명": { "레벨명": ["항목", ...] } }
const ESDM_ITEMS_KEY = "gd-aba-esdm-items";

const AUTH_CURRENT_USER_KEY = "gd-aba-current-user";  // 현재 로그인 정보 {role, name}

function simpleHash(str) {
  let hash = 0;
  if (!str || str.length === 0) return "0";
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + ch;
    hash = hash & hash;  // 32bit
  }
  return String(hash);
}

// ★ 강화된 비밀번호 해싱 — PBKDF2 + SHA-256 (브라우저 내장 crypto)
//   형식: "pbkdf2$<반복수>$<salt(hex)>$<hash(hex)>"  — simpleHash와 구분됨
const PBKDF2_ITER = 120000;
function _bufToHex(buf) {
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, "0")).join("");
}
function _hexToBuf(hex) {
  const arr = new Uint8Array(hex.length / 2);
  for (let i = 0; i < arr.length; i++) arr[i] = parseInt(hex.substr(i * 2, 2), 16);
  return arr;
}
async function hashPasswordSecure(password, saltHex) {
  // saltHex 없으면 새로 생성 (신규 비번), 있으면 그대로 (검증용)
  const enc = new TextEncoder();
  const salt = saltHex ? _hexToBuf(saltHex) : crypto.getRandomValues(new Uint8Array(16));
  const keyMaterial = await crypto.subtle.importKey("raw", enc.encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", salt, iterations: PBKDF2_ITER, hash: "SHA-256" },
    keyMaterial, 256
  );
  const saltOut = saltHex || _bufToHex(salt.buffer);
  return `pbkdf2$${PBKDF2_ITER}$${saltOut}$${_bufToHex(bits)}`;
}
// 비밀번호 검증 — 저장된 해시가 PBKDF2면 PBKDF2로, 옛 simpleHash면 옛 방식으로 (기존 비번 호환)
async function verifyPassword(password, storedHash) {
  if (!storedHash) return false;
  if (typeof storedHash === "string" && storedHash.startsWith("pbkdf2$")) {
    const parts = storedHash.split("$");
    if (parts.length !== 4) return false;
    const saltHex = parts[2];
    try {
      const computed = await hashPasswordSecure(password, saltHex);
      return computed === storedHash;
    } catch (e) { return false; }
  }
  // 옛 형식 (simpleHash) — 기존 비번 그대로 인정
  return simpleHash(password) === storedHash;
}
// 저장된 해시가 옛 형식인지 (로그인 후 자동 업그레이드 판단용)
function isLegacyHash(storedHash) {
  return typeof storedHash === "string" && !storedHash.startsWith("pbkdf2$");
}

const ARCHIVE_INDEX_PREFIX = "gd-aba-archives:";  // + childId → 인덱스 배열
const ARCHIVE_ITEM_PREFIX = "gd-aba-archive:";    // + archiveId → 개별 스냅샷

function fmtArchivePeriod(start, end) {
  const s = start ? String(start).slice(0, 7).replace("-", ".") : "";
  const e = end ? String(end).slice(0, 7).replace("-", ".") : "";
  if (s && e) return `${s}~${e}`;
  if (s) return s;
  if (e) return e;
  return new Date().toISOString().slice(0, 7).replace("-", ".");
}

// ★ 컷오프 기준 날짜 — "이번에 보고한 마지막 데이터 날짜"(cutoffDataDate)를 우선 사용.
//   컷오프 후 다음 보고서는 이 날짜 '이후' 새로 찍힌 데이터부터 시작.
//   옛 아카이브(cutoffDataDate 없음)는 보고 기간 정보로 역산 — savedAt(저장 시각)은 최후 수단.
function isValidYmd(s) {
  return typeof s === "string" && /^\d{4}-\d{2}-\d{2}$/.test(s);
}
// "2026.07" 또는 "2026.03~2026.07" → 종료월의 말일 "2026-07-31"
function periodEndToDate(period) {
  if (!period || typeof period !== "string") return null;
  const parts = period.split("~");
  const last = (parts[parts.length - 1] || "").trim();       // "2026.07"
  const m = last.match(/^(\d{4})\.(\d{2})$/);
  if (!m) return null;
  const year = parseInt(m[1], 10);
  const month = parseInt(m[2], 10);
  if (!year || !month || month < 1 || month > 12) return null;
  const lastDay = new Date(year, month, 0).getDate();        // 그 달 말일
  return `${m[1]}-${m[2]}-${String(lastDay).padStart(2, "0")}`;
}
function cutoffOf(item) {
  if (!item) return null;
  // 1) 신규: 이번 보고 마지막 데이터 날짜
  if (isValidYmd(String(item.cutoffDataDate || "").slice(0, 10))) {
    return String(item.cutoffDataDate).slice(0, 10);
  }
  // 2) 옛 아카이브: 저장된 보고 종료일(prevEvalEnd)이 유효한 날짜면 사용
  if (isValidYmd(String(item.prevEvalEnd || "").slice(0, 10))) {
    return String(item.prevEvalEnd).slice(0, 10);
  }
  // 3) 그다음: 보고 기간 문자열의 종료월 말일로 역산
  const pe = periodEndToDate(item.period);
  if (pe) return pe;
  // 4) 최후: 저장 시각
  return item.savedAt ? String(item.savedAt).slice(0, 10) : null;
}

// ★ [보관 A-1] 보관 목록(인덱스)은 클라우드가 원본이다 — 로컬은 예비용.
//    옛 코드는 로컬을 먼저 읽고 값이 있으면 클라우드를 아예 보지 않았다.
//    아티팩트 시절(서버 없음)엔 맞는 순서였지만, window.storage가 Supabase로
//    바뀐 뒤로는 뜻이 뒤집혔다 — 예비용이 아니라 원본이 됐다.
//    그 결과 선생님마다 목록이 다르게 보이고, 저장할 때 낡은 로컬 목록이
//    클라우드를 덮어써서 다른 선생님이 넣은 보고서가 목록에서 사라졌다.
//    ([95-1]에서 아동 데이터에 났던 사고와 같은 패턴. 보관함은 그때 손대지 않았다.)
//
//    본문(ARCHIVE_ITEM_PREFIX)은 id가 고유해 서로 덮을 일이 없으므로
//    로컬 우선을 그대로 둔다 — 클라우드 전송량도 아낀다. 충돌은 인덱스에서만 난다.

// 클라우드 인덱스를 직접 읽는다.
//   { ok: true }  = 응답 정상 (list가 비면 '아직 저장된 적 없음')
//   { ok: false } = 네트워크·서버 장애
// 이 구분이 핵심이다. 장애를 '비어 있음'으로 오해하고 로컬 목록을 올리면
// 클라우드의 멀쩡한 목록을 통째로 날린다.
async function readCloudArchiveIndex(childId) {
  if (typeof window === "undefined" || !window.storage) return { ok: false, list: [] };
  try {
    const r = await window.storage.get(ARCHIVE_INDEX_PREFIX + childId);
    if (!r || !r.value) return { ok: true, list: [] };
    const list = JSON.parse(r.value);
    return { ok: true, list: Array.isArray(list) ? list : [] };
  } catch (e) {
    console.warn("[보관 인덱스 클라우드 읽기 실패]", childId, e);
    return { ok: false, list: [] };
  }
}

function readLocalArchiveIndex(childId) {
  try {
    if (typeof localStorage === "undefined") return null;
    const raw = localStorage.getItem(ARCHIVE_INDEX_PREFIX + childId);
    if (!raw) return null;
    const list = JSON.parse(raw);
    return Array.isArray(list) ? list : null;
  } catch (e) { return null; }
}

function writeLocalArchiveIndex(childId, list) {
  try {
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(ARCHIVE_INDEX_PREFIX + childId, JSON.stringify(list));
    }
  } catch (e) {}
}

function sortArchiveList(list) {
  return [...list].sort((a, b) => (b.savedAt || "").localeCompare(a.savedAt || ""));
}

async function loadArchiveList(childId) {
  if (!childId) return [];
  const cloud = await readCloudArchiveIndex(childId);
  if (cloud.ok) {
    if (cloud.list.length > 0) {
      writeLocalArchiveIndex(childId, cloud.list);   // 로컬은 캐시로만 갱신
      return sortArchiveList(cloud.list);
    }
    // 클라우드에 아직 없는 아동 — 이 기기에만 남은 옛 사본이 있으면 그걸 쓴다
    const local = readLocalArchiveIndex(childId);
    if (local && local.length > 0) return sortArchiveList(local);
    return [];
  }
  // 클라우드 장애 — 로컬로 버틴다 (쓰기는 saveArchiveItem에서 막는다)
  const local = readLocalArchiveIndex(childId);
  return local ? sortArchiveList(local) : [];
}

async function loadArchiveItem(archiveId) {
  if (!archiveId) return null;
  try {
    if (typeof localStorage !== "undefined") {
      const raw = localStorage.getItem(ARCHIVE_ITEM_PREFIX + archiveId);
      if (raw) return JSON.parse(raw);
    }
    if (typeof window !== "undefined" && window.storage) {
      const r = await window.storage.get(ARCHIVE_ITEM_PREFIX + archiveId);
      if (r?.value) return JSON.parse(r.value);
    }
  } catch (e) {}
  return null;
}

async function saveArchiveItem(snapshot, autoMode) {
  if (!snapshot || !snapshot.childId) return null;
  try {
    const childId = snapshot.childId;
    // ★ [보관 A-2] 목록은 반드시 클라우드 최신본 위에 얹는다.
    //    loadArchiveList를 쓰면 '클라우드가 비었다'와 '클라우드를 못 읽었다'가
    //    구분되지 않는다. 장애 상황에서 로컬 목록으로 클라우드를 덮으면
    //    다른 선생님 보고서가 목록에서 사라진다 — 지금 고치려는 그 사고다.
    const cloudIdx = await readCloudArchiveIndex(childId);
    const cloudIndexOk = cloudIdx.ok;
    let list = (cloudIndexOk && cloudIdx.list.length > 0)
      ? cloudIdx.list
      : (readLocalArchiveIndex(childId) || []);
    if (autoMode) {
      const now = Date.now();
      const sameRecent = list.find(item =>
        item.auto === true &&
        item.period === snapshot.period &&
        (now - new Date(item.savedAt || 0).getTime() < 24 * 3600 * 1000)
      );
      if (sameRecent) {
        const fullId = sameRecent.id;
        const fullSnap = { ...snapshot, id: fullId, order: sameRecent.order, auto: true, savedAt: new Date().toISOString() };
        try {
          if (typeof localStorage !== "undefined") localStorage.setItem(ARCHIVE_ITEM_PREFIX + fullId, JSON.stringify(fullSnap));
        } catch (e) {}
        try {
          if (typeof window !== "undefined" && window.storage) {
            await window.storage.set(ARCHIVE_ITEM_PREFIX + fullId, JSON.stringify(fullSnap)).catch(() => {});
          }
        } catch (e) {}
        list = list.map(item => item.id === fullId ? { ...item, savedAt: fullSnap.savedAt, cutoffDataDate: fullSnap.cutoffDataDate || item.cutoffDataDate || "" } : item);
        try {
          if (typeof localStorage !== "undefined") localStorage.setItem(ARCHIVE_INDEX_PREFIX + childId, JSON.stringify(list));
        } catch (e) {}
        try {
          // 클라우드 목록을 못 읽었으면 올리지 않는다 — 덮어쓰면 남의 보고서가 지워진다.
          if (cloudIndexOk && typeof window !== "undefined" && window.storage) {
            await window.storage.set(ARCHIVE_INDEX_PREFIX + childId, JSON.stringify(list)).catch(() => {});
          } else if (!cloudIndexOk) {
            console.warn("[보관] 클라우드 목록을 읽지 못해 이 기기에만 저장했습니다.", childId);
          }
        } catch (e) {}
        return { id: fullId, overwrite: true, savedAt: fullSnap.savedAt, cloudIndexSkipped: !cloudIndexOk };
      }
    }
    const id = "rpt_" + Date.now() + "_" + Math.random().toString(36).slice(2, 6);
    const order = (list.length || 0) + 1;
    const fullSnap = { ...snapshot, id, order, auto: !!autoMode, savedAt: new Date().toISOString() };
    try {
      if (typeof localStorage !== "undefined") localStorage.setItem(ARCHIVE_ITEM_PREFIX + id, JSON.stringify(fullSnap));
    } catch (e) {}
    try {
      if (typeof window !== "undefined" && window.storage) {
        await window.storage.set(ARCHIVE_ITEM_PREFIX + id, JSON.stringify(fullSnap)).catch(() => {});
      }
    } catch (e) {}
    const indexEntry = { id, title: fullSnap.title, period: fullSnap.period, order, savedAt: fullSnap.savedAt, auto: fullSnap.auto, isFinal: fullSnap.isFinal || false, isIep: fullSnap.isIep || false, prevEvalStart: fullSnap.prevEvalStart || "", prevEvalEnd: fullSnap.prevEvalEnd || "", cutoffDataDate: fullSnap.cutoffDataDate || "" };
    const newList = [...list, indexEntry];
    try {
      if (typeof localStorage !== "undefined") localStorage.setItem(ARCHIVE_INDEX_PREFIX + childId, JSON.stringify(newList));
    } catch (e) {}
    try {
      // 위와 같은 이유 — 클라우드 목록을 못 읽은 상태에서는 올리지 않는다.
      if (cloudIndexOk && typeof window !== "undefined" && window.storage) {
        await window.storage.set(ARCHIVE_INDEX_PREFIX + childId, JSON.stringify(newList)).catch(() => {});
      } else if (!cloudIndexOk) {
        console.warn("[보관] 클라우드 목록을 읽지 못해 이 기기에만 저장했습니다.", childId);
      }
    } catch (e) {}
    return { id, overwrite: false, savedAt: fullSnap.savedAt, cloudIndexSkipped: !cloudIndexOk };
  } catch (e) {
    console.warn("[보관] 저장 실패:", e);
    return null;
  }
}

async function deleteArchiveItem(childId, archiveId) {
  if (!childId || !archiveId) return false;
  try {
    try {
      if (typeof localStorage !== "undefined") localStorage.removeItem(ARCHIVE_ITEM_PREFIX + archiveId);
    } catch (e) {}
    try {
      if (typeof window !== "undefined" && window.storage) {
        await window.storage.delete(ARCHIVE_ITEM_PREFIX + archiveId).catch(() => {});
      }
    } catch (e) {}
    // ★ [보관 A-3] 삭제도 클라우드 최신 목록에서 빼야 한다.
    //    낡은 로컬 목록에서 하나만 빼서 올리면, 그 사이 다른 선생님이 넣은
    //    보고서까지 함께 사라진다.
    const cloudIdx = await readCloudArchiveIndex(childId);
    const cloudIndexOk = cloudIdx.ok;
    const list = (cloudIndexOk && cloudIdx.list.length > 0)
      ? cloudIdx.list
      : (readLocalArchiveIndex(childId) || []);
    const newList = list.filter(item => item.id !== archiveId);
    writeLocalArchiveIndex(childId, newList);
    try {
      if (cloudIndexOk && typeof window !== "undefined" && window.storage) {
        await window.storage.set(ARCHIVE_INDEX_PREFIX + childId, JSON.stringify(newList)).catch(() => {});
      } else if (!cloudIndexOk) {
        console.warn("[보관] 클라우드 목록을 읽지 못해 삭제가 이 기기에만 반영됐습니다.", childId);
      }
    } catch (e) {}
    return true;
  } catch (e) {
    return false;
  }
}

